if (js::startsWith(data, "Display ")) {
  const std::vector<std::string> lines = js::map(js::split(data, "\n"), [](const std::string& l) { return js::trim(l); });
  // ii: 找不到这两行时 JS 在 .split 处抛 TypeError，这一项不会 push
  const std::optional<std::string> connector =
      js::find(lines, [](const std::string& l) { return js::startsWith(l, "DRM connector:"); });
  if (!connector) {
    return;
  }
  DdcMonitor entry;
  entry.name = js::join(js::slice(js::split(*connector, "-"), 1), "-");
  const std::optional<std::string> bus = js::find(lines, [](const std::string& l) { return js::startsWith(l, "I2C bus:"); });
  if (!bus) {
    return;
  }
  const std::vector<std::string> busParts = js::split(*bus, "/dev/i2c-");
  // ii: 行里没有 "/dev/i2c-" 时 busNum 是 undefined，结构体里只能存成 ""（ddcutil 总会输出这一段）
  entry.busNum = busParts.size() > 1 ? busParts[1] : std::string();
  // var 数组的 push 是原地修改、不发 ddcMonitorsChanged；这里只能整体写回，没有绑定或处理函数依赖它的变化
  std::vector<DdcMonitor> list = ddcMonitors.get();
  list.push_back(std::move(entry));
  ddcMonitors.set(std::move(list));
}

