// Math.max 遇 NaN 得 NaN（std::max 不会），这里照 JS 保留 NaN
const double multiplied = this->multipliedBrightness.get();
const double brightnessValue = std::isnan(multiplied) ? multiplied : std::max(multiplied, 0.0);
auto& root = ::ii::services::Brightness::instance();
if (this->isDdc.get()) {
  const double floored = std::floor(brightnessValue * this->rawMaxBrightness.get());
  const double rawValueRounded = std::isnan(floored) ? floored : std::max(floored, 1.0);
  root.setProc->exec(std::vector<std::string>{"ddcutil", "-b", this->busNum.get(), "setvcp", "10", js::toString(rawValueRounded)});
} else {
  const double valuePercentNumber = std::floor(brightnessValue * 100);
  std::string valuePercent = js::toString(valuePercentNumber) + "%";
  if (valuePercentNumber == 0) {
    valuePercent = "1";  // Prevent fully black
  }
  root.setProc->exec(std::vector<std::string>{"brightnessctl", "--class", "backlight", "s", valuePercent, "--quiet"});
}

